#include <stdarg.h>
#include <stdio.h>
#include <stdlib.h>
#include <wchar.h>

void safe_fprintf(FILE *f, const char *fmt, ...) {
    va_list args;
    va_start(args, fmt);

    char stack_buf[1024];
    int len = vsnprintf(stack_buf, sizeof(stack_buf), fmt, args);
    va_end(args);

    if (len < 0) {
        // An error occurred in formatting, return without printing
        return;
    }

    if (len < sizeof(stack_buf)) {
        // Stack buffer is sufficient, no heap allocation needed
        fputs(stack_buf, f);
        return;
    }

    // Need to allocate a buffer on the heap
    char *heap_buf = malloc(len + 1);
    if (!heap_buf) {
        // Allocation failed, return without printing
        return;
    }

    va_start(args, fmt);
    len = vsnprintf(heap_buf, len + 1, fmt, args);
    va_end(args);

    if (len < 0) {
        // An error occurred in formatting
        free(heap_buf);
        return;
    }

    // Process the buffer to handle non-printable characters
    for (int i = 0; i < len; i++) {
        if (isprint((unsigned char)heap_buf[i])) {
            fputc(heap_buf[i], f);
        } else {
            // Handle non-printable characters
            wchar_t wc;
            char mb[MB_CUR_MAX];
            mb[0] = '\0';
            if (mbtowc(&wc, &heap_buf[i], 1) == 1) {
                if (iswprint(wc)) {
                    // Wide character is printable, print it
                    fputwc(wc, f);
                } else {
                    // Wide character is not printable, replace with a default character
                    fputc('?', f);
                }
            } else {
                // Invalid or unprintable character
                fputc('?', f);
            }
        }
    }

    free(heap_buf);
}

