void safe_fprintf(FILE *f, const char *fmt, ...) {
    char stack_buffer[1024];
    va_list args;
    int result;
    char *heap_buffer = NULL;
    size_t heap_buffer_size = 0;

    va_start(args, fmt);
    result = vsnprintf(stack_buffer, sizeof(stack_buffer), fmt, args);
    va_end(args);

    if (result < 0) {
        return;  // Error in formatting
    }

    if (result < sizeof(stack_buffer)) {
        // Stack buffer is sufficient
        fputs(stack_buffer, f);
        return;
    }

    // Need to allocate heap buffer
    heap_buffer_size = result + 1;
    heap_buffer = (char *)malloc(heap_buffer_size);
    if (heap_buffer == NULL) {
        return;  // Memory allocation failed
    }

    va_start(args, fmt);
    result = vsnprintf(heap_buffer, heap_buffer_size, fmt, args);
    va_end(args);

    if (result < 0) {
        free(heap_buffer);
        return;  // Error in formatting
    }

    // Check for unprintable wide characters
    size_t i = 0;
    while (heap_buffer[i] != '\0') {
        if (!isprint((unsigned char)heap_buffer[i])) {
            wchar_t wc;
            char mb_char[MB_CUR_MAX];
            mbstate_t state = {0};
            size_t converted = mbtowc(&wc, &heap_buffer[i], 1);
            if (converted == 0 || converted == (size_t)-1) {
                // Handle error or unprintable character
                fputc('?', f);
            } else {
                size_t rc = wctomb(mb_char, wc);
                if (rc == 0 || rc == (size_t)-1) {
                    // Handle error or unprintable character
                    fputc('?', f);
                } else {
                    fwrite(mb_char, sizeof(char), rc, f);
                }
            }
        } else {
            fputc(heap_buffer[i], f);
        }
        i++;
    }

    free(heap_buffer);
}

