#include <wctype.h>

void safe_fprint(FILE *f, const char *fmt, ...) {
    char stack_buffer[1024];
    va_list args;
    va_start(args, fmt);
    int result = vsnprintf(stack_buffer, sizeof(stack_buffer), fmt, args);
    va_end(args);

    if (result < 0 || result < sizeof(stack_buffer)) {
        // Stack buffer is sufficient
        fprintf(f, "%s", stack_buffer);
    } else {
        // Stack buffer was too small, allocate a heap buffer
        char *heap_buffer = malloc(result + 1);
        if (heap_buffer == NULL) {
            // Memory allocation failed, fallback to printing the error
            fprintf(f, "Error: Failed to allocate memory for formatted string.\n");
            return;
        }

        va_start(args, fmt);
        vsnprintf(heap_buffer, result + 1, fmt, args);
        va_end(args);

        // Process characters to ensure all wide characters are printable
        for (size_t i = 0; i < result; i++) {
            wchar_t wc;
            mbtowc(&wc, &heap_buffer[i], 1);
            if (iswprint(wc)) {
                fputc(heap_buffer[i], f);
            } else {
                // Replace unprintable characters with a placeholder
                fputs("[unprintable]", f);
            }
        }

        free(heap_buffer);
    }
}

