void formatted_print(FILE *f, const char *fmt, ...) {
    char buffer[1024];
    va_list args;
    int len;
    va_start(args, fmt);

    // First try with stack buffer
    len = vsnprintf(buffer, sizeof(buffer), fmt, args);
    va_end(args);

    if (len < 0 || len < sizeof(buffer)) {
        // If buffer is sufficient or vsnprintf reports error, use stack buffer
        size_t i;
        wchar_t wc;
        mbstate_t state = {0};
        char output[4];

        for (i = 0; i < sizeof(buffer); i++) {
            if (buffer[i] == '\0') break;

            // Check if character is printable
            if (isprint(buffer[i])) {
                fputc(buffer[i], f);
            } else {
                // Convert to wide character and print as hexadecimal
                if (mbtowc(&wc, &buffer[i], MB_CUR_MAX, &state) == 1) {
                    if (iswprint(wc)) {
                        fputwc(wc, f);
                    } else {
                        // Print unprintable as \xHH
                        fprintf(f, "\\x%02X", (unsigned char)buffer[i]);
                    }
                } else {
                    // Fallback to printing as \xHH
                    fprintf(f, "\\x%02X", (unsigned char)buffer[i]);
                }
            }
        }
    } else {
        // If stack buffer is not enough, allocate heap buffer
        char *heap_buffer = malloc(len + 1);
        if (!heap_buffer) {
            return;
        }

        va_start(args, fmt);
        vsnprintf(heap_buffer, len + 1, fmt, args);
        va_end(args);

        size_t i;
        wchar_t wc;
        mbstate_t state = {0};
        char output[4];

        for (i = 0; i < len; i++) {
            if (heap_buffer[i] == '\0') break;

            if (isprint(heap_buffer[i])) {
                fputc(heap_buffer[i], f);
            } else {
                if (mbtowc(&wc, &heap_buffer[i], MB_CUR_MAX, &state) == 1) {
                    if (iswprint(wc)) {
                        fputwc(wc, f);
                    } else {
                        fprintf(f, "\\x%02X", (unsigned char)heap_buffer[i]);
                    }
                } else {
                    fprintf(f, "\\x%02X", (unsigned char)heap_buffer[i]);
                }
            }
        }

        free(heap_buffer);
    }
}

