#define INITIAL_BUFFER_SIZE 256

void safe_print_to_file(FILE *f, const char *fmt, ...) {
    va_list args;
    char buffer[INITIAL_BUFFER_SIZE];
    char *heap_buffer = NULL;
    size_t buffer_size = INITIAL_BUFFER_SIZE;
    int result;
    va_start(args, fmt);

    // First attempt to format using stack-allocated buffer
    result = vsnprintf(buffer, buffer_size, fmt, args);
    va_end(args);

    if (result < 0) {
        // Formatting failed, return without printing
        return;
    }

    if (result < buffer_size) {
        // Successfully fit into stack buffer, print and return
        fputs(buffer, f);
        return;
    }

    // Allocate a heap buffer of appropriate size
    heap_buffer = (char *)malloc(result + 1);
    if (heap_buffer == NULL) {
        // Out of memory, return without printing
        return;
    }

    // Reformat into the heap buffer
    va_start(args, fmt);
    vsnprintf(heap_buffer, result + 1, fmt, args);
    va_end(args);

    // Check for non-printable characters and replace them
    char *output = heap_buffer;
    char *input = heap_buffer;
    mbtowc(NULL, NULL, 0); // Reset mbtowc state

    while (*input) {
        wchar_t wc;
        size_t s = mbtowc(&wc, input, MB_CUR_MAX);
        if (s == 0 || s == (size_t)(-1) || iswprint(wc) == 0) {
            // Replace non-printable with a placeholder
            snprintf(output, 4, "\\x%02X", (unsigned char)*input);
            output += 4;
            input++;
        } else {
            // Copy printable character
            while (s-- > 0) {
                *output++ = *input++;
            }
        }
    }

    *output = '\0';

    // Print the resulting string
    fputs(heap_buffer, f);

    // Free the heap buffer
    free(heap_buffer);
}
